-- =====================================================================
-- car_service 测试数据脚本
-- 11 张业务表,共 222 行(每张 20 条 + wording_mgmt 22 条)
--
-- 关联约定:
--   user_id              → ruoyi-vue-pro.system_users 真实用户 ID
--                          (1/100/103/104/112/114/115/117/118/139,共 10 个)
--   rescue_user_id       → 工作人员,用 [1,100,103,104] 4 个
--   audit_user_id        → 审核人员,用 [1,100,103,104]
--   handle_user_id       → 处置人员,用 [1,100,103]
--   mediate_user_id      → 调解人员,用 [1,100]
--   station_id           → mock 区段 [2001..2010]
--   space_id             → mock 区段 [3001..3050]
--   merchant_id          → mock 区段 [5001..5010]
--   order_id             → mock 区段 [7001..7020]
--
-- 状态字段按字典严格分布,字段值与字典 system_dict_data 对齐
-- 时间梯度:create_time 在近 30 天内,趋势图能看到分布
-- 车牌号:闽 C/D/E + 5 位字符,真实福建格式
-- 地址:福建闽南真实地点
--
-- 由 mysqldump 自动导出,数据快照时间见文件 mtime
-- 重新生成命令:
--   mysqldump -uroot -p car_service \
--     --no-create-info --skip-extended-insert --complete-insert \
--     rescue_info reserve_list space_push suggestion user_appeal dispute_mediate \
--     wording_mgmt charge_park_map near_station space_location path_plan
--
-- 执行方式(注意:会清空 11 张表的现有数据):
--   mysql -uroot -p car_service < sql/test_data.sql
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 清空 11 张业务表(TRUNCATE 会重置自增 ID,确保导入后 ID 完全匹配)
TRUNCATE TABLE rescue_info;
TRUNCATE TABLE reserve_list;
TRUNCATE TABLE space_push;
TRUNCATE TABLE suggestion;
TRUNCATE TABLE user_appeal;
TRUNCATE TABLE dispute_mediate;
TRUNCATE TABLE wording_mgmt;
TRUNCATE TABLE charge_park_map;
TRUNCATE TABLE near_station;
TRUNCATE TABLE space_location;
TRUNCATE TABLE path_plan;


SET FOREIGN_KEY_CHECKS = 1;
